# Tests of the identity, administrator and API client checks (MP.JAMF.1002 to MP.JAMF.1011).
Describe 'Jamf Pro pack: identity, administrators and API clients' {
    BeforeAll {
        . "$PSScriptRoot/Fixture.ps1"
        Import-JamfSpecMaester

        $script:GroupsKey = 'paged:api/v1/account-groups?'
        $script:RolesKey = 'paged:api/v1/api-roles?'
        $script:ClientsKey = 'paged:api/v1/api-integrations?'

        function New-IdentitySpecAccount {
            <# One Jamf Pro account in the shape GET /api/v1/accounts returns. #>
            param(
                [string] $Username = 'admin',
                [string] $Privilege = 'ADMINISTRATOR',
                [string] $Access = 'FullAccess',
                [string] $Type = 'DEFAULT',
                [int] $LdapServerId = -1,
                [int] $PasswordAgeDays = 10,
                [switch] $NoPasswordChange
            )
            $account = @{
                id = [string](Get-Random -Maximum 100000); username = $Username; realname = $Username
                ldapServerId = $LdapServerId; siteId = -1; accessLevel = $Access; privilegeLevel = $Privilege
                accountStatus = 'Enabled'; accountType = $Type; changePasswordOnNextLogin = $false; failedLoginAttempts = 0
            }
            if (-not $NoPasswordChange) { $account.lastPasswordChange = [datetime]::UtcNow.AddDays(-$PasswordAgeDays).ToString('o') }
            $account
        }

        function New-IdentitySpecGroup {
            <# One Jamf Pro account group in the shape GET /api/v1/account-groups returns. #>
            param([string] $Name = 'Admins', [string[]] $Members = @(), [string] $LdapServerId = '-1', [string] $Privilege = 'ADMINISTRATOR')
            @{
                id = [string](Get-Random -Maximum 100000); name = $Name; accessLevel = 'FullAccess'; privilegeLevel = $Privilege
                siteId = '-1'; ldapServerId = $LdapServerId
                members = @($Members | ForEach-Object { @{ id = [string](Get-Random -Maximum 100000); username = $_ } })
            }
        }

        function New-IdentitySpecClientCache {
            <#
            The API roles and clients caches. -Clients is a list of hashtables with Name, Roles, and optionally
            ClientId, Lifetime and Enabled; -Roles maps role names to privileges.
            #>
            param([hashtable] $Roles, [object[]] $Clients)
            $i = 0
            @{
                $script:RolesKey   = @($Roles.GetEnumerator() | ForEach-Object { @{ id = [string](++$i); displayName = $_.Key; privileges = @($_.Value) } })
                $script:ClientsKey = @($Clients | ForEach-Object {
                        @{
                            id = ++$i; displayName = $_.Name; clientId = if ($_.ClientId) { $_.ClientId } else { "id-$($_.Name)" }
                            enabled = if ($_.ContainsKey('Enabled')) { $_.Enabled } else { $true }
                            authorizationScopes = @($_.Roles); appType = 'CLIENT_CREDENTIALS'
                            accessTokenLifetimeSeconds = if ($_.Lifetime) { $_.Lifetime } else { 300 }
                        }
                    })
            }
        }

        $script:SsoOn = @{ ssoEnabled = $true; ssoBypassAllowed = $false; configurationType = 'SAML'; samlSettings = @{ idpProviderType = 'AZURE'; metadataSource = 'URL'; idpUrl = 'https://login.microsoftonline.com/tenant/federationmetadata/2007-06/federationmetadata.xml' } }
    }

    Context 'the new files' {
        It 'are valid native tests with a guide: <_>' -ForEach @('1002', '1003', '1004', '1005', '1006', '1007', '1008', '1009', '1010', '1011') {
            $file = Join-Path $script:PackRoot "tests/Test.MP.JAMF.$_.ps1"
            $test = Get-MtTest -Path $file
            $test.Errors | Should -BeNullOrEmpty
            $test.IsValid | Should -BeTrue
        }
    }

    Context 'MP.JAMF.1002 single sign-on bypass' {
        It 'passes when users cannot bypass SSO' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1002 -Cache @{ 'api/v3/sso' = $script:SsoOn }
            $row.Result | Should -Be 'Passed'
            $row.Benchmark.Requirement | Should -Be 'V-241797'
        }

        It 'fails when the bypass is allowed' {
            $sso = $script:SsoOn.Clone(); $sso.ssoBypassAllowed = $true
            (Invoke-JamfSpecTest -Id MP.JAMF.1002 -Cache @{ 'api/v3/sso' = $sso }).Result | Should -Be 'Failed'
        }

        It 'is not applicable when SSO is off' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1002 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $false; ssoBypassAllowed = $true } }
            $row.Result | Should -Be 'Skipped'
            $row.ReasonCode | Should -Be 'NotApplicable'
        }
    }

    Context 'MP.JAMF.1003 SAML identity provider over HTTPS' {
        It 'passes with an https metadata URL' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1003 -Cache @{ 'api/v3/sso' = $script:SsoOn }).Result | Should -Be 'Passed'
        }

        It 'fails with an http metadata URL' {
            $sso = @{ ssoEnabled = $true; configurationType = 'OIDC_WITH_SAML'; samlSettings = @{ idpProviderType = 'OKTA'; metadataSource = 'URL'; idpUrl = 'http://idp.contoso.com/metadata' } }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1003 -Cache @{ 'api/v3/sso' = $sso }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'http://idp.contoso.com'
        }

        It 'asks for a review when the metadata was uploaded as a file' {
            $sso = @{ ssoEnabled = $true; configurationType = 'SAML'; samlSettings = @{ idpProviderType = 'ADFS'; metadataSource = 'FILE'; idpUrl = '' } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1003 -Cache @{ 'api/v3/sso' = $sso }).Result | Should -Be 'Investigate'
        }

        It 'is not applicable with OIDC only' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1003 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $true; configurationType = 'OIDC' } }
            $row.Result | Should -Be 'Skipped'
            $row.ReasonCode | Should -Be 'NotApplicable'
        }

        It 'is not applicable when SSO is off' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1003 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $false; configurationType = 'SAML' } }).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1004 full administrators' {
        It 'passes with few administrators and counts a person once' {
            $cache = @{
                (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'alice'), (New-IdentitySpecAccount -Username 'bob'), (New-IdentitySpecAccount -Username 'auditor' -Privilege 'AUDITOR'))
                $script:GroupsKey            = @((New-IdentitySpecGroup -Name 'Jamf Admins' -Members 'Alice', 'carol'))
            }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1004 -Cache $cache
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match '3 accounts or groups'
            $row.ResultDetail.TestResult | Should -Not -Match 'auditor'
        }

        It 'fails above the maximum and names a directory group without members' {
            $cache = @{
                (Get-JamfSpecQuery Accounts) = @(1..5 | ForEach-Object { New-IdentitySpecAccount -Username "admin$_" })
                $script:GroupsKey            = @((New-IdentitySpecGroup -Name 'Entra Jamf Admins' -LdapServerId '1'))
            }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1004 -Cache $cache
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Entra Jamf Admins \(group, members not listed\)'
        }

        It 'takes the limit from MaximumAdministrators' {
            $cache = @{
                (Get-JamfSpecQuery Accounts) = @(1..5 | ForEach-Object { New-IdentitySpecAccount -Username "admin$_" })
                $script:GroupsKey            = @((New-IdentitySpecGroup -Name 'Entra Jamf Admins' -LdapServerId '1'))
            }
            (Invoke-JamfSpecTest -Id MP.JAMF.1004 -Cache $cache -Parameter @{ MaximumAdministrators = 6 }).Result | Should -Be 'Passed'
        }
    }

    Context 'MP.JAMF.1005 local accounts with SSO' {
        It 'passes when only break-glass accounts are local' {
            $cache = @{
                'api/v3/sso'                 = $script:SsoOn
                (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'breakglass1'), (New-IdentitySpecAccount -Username 'breakglass2'), (New-IdentitySpecAccount -Username 'breakglass3'), (New-IdentitySpecAccount -Username 'sso.user' -Type 'FEDERATED'), (New-IdentitySpecAccount -Username 'ldap.user' -LdapServerId 1))
            }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1005 -Cache $cache -Parameter @{ BreakGlassAccounts = @('breakglass1', 'breakglass2', 'breakglass3') }
            $row.Result | Should -Be 'Passed'
            $row.Benchmark.Requirement | Should -Be 'V-241817'
        }

        It 'fails with more local accounts than allowed' {
            $cache = @{
                'api/v3/sso'                 = $script:SsoOn
                (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'admin'), (New-IdentitySpecAccount -Username 'jss'), (New-IdentitySpecAccount -Username 'helpdesk'), (New-IdentitySpecAccount -Username 'sso.user' -Type 'FEDERATED'))
            }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1005 -Cache $cache
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'helpdesk'
            $row.ResultDetail.TestResult | Should -Not -Match 'sso.user'
        }

        It 'takes the limit from MaximumLocalAccounts' {
            $cache = @{
                'api/v3/sso'                 = $script:SsoOn
                (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'admin'))
            }
            (Invoke-JamfSpecTest -Id MP.JAMF.1005 -Cache $cache -Parameter @{ MaximumLocalAccounts = 0 }).Result | Should -Be 'Failed'
        }

        It 'is not applicable when SSO is off' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1005 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $false } }
            $row.Result | Should -Be 'Skipped'
            $row.ReasonCode | Should -Be 'NotApplicable'
        }
    }

    Context 'MP.JAMF.1006 local account password age' {
        It 'passes when every local password is recent' {
            $cache = @{ (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'admin' -PasswordAgeDays 30), (New-IdentitySpecAccount -Username 'old.ldap' -LdapServerId 1 -PasswordAgeDays 900)) }
            (Invoke-JamfSpecTest -Id MP.JAMF.1006 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails for an old or unrecorded password and leaves out break-glass accounts' {
            $cache = @{ (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'admin' -PasswordAgeDays 400), (New-IdentitySpecAccount -Username 'never' -NoPasswordChange), (New-IdentitySpecAccount -Username 'breakglass' -PasswordAgeDays 900)) }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1006 -Cache $cache -Parameter @{ BreakGlassAccounts = @('breakglass') }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Not recorded'
            $row.ResultDetail.TestResult | Should -Not -Match 'breakglass'
        }

        It 'takes the age from MaximumPasswordAgeDays' {
            $cache = @{ (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'admin' -PasswordAgeDays 100)) }
            (Invoke-JamfSpecTest -Id MP.JAMF.1006 -Cache $cache -Parameter @{ MaximumPasswordAgeDays = 90 }).Result | Should -Be 'Failed'
        }

        It 'is skipped when there is no local account' {
            $cache = @{ (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'sso.user' -Type 'FEDERATED')) }
            (Invoke-JamfSpecTest -Id MP.JAMF.1006 -Cache $cache).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1007 API clients and device secrets' {
        It 'passes when no client can read secrets' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers', 'Read Mobile Devices') } -Clients @(@{ Name = 'Inventory sync'; Roles = @('Read Only') })
            (Invoke-JamfSpecTest -Id MP.JAMF.1007 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails and lists a client that can read recovery keys, but not a disabled one' {
            $roles = @{ 'Recovery keys' = @('Read Computers', 'View Disk Encryption Recovery Key'); 'LAPS' = @('View Local Admin Password') }
            $cache = New-IdentitySpecClientCache -Roles $roles -Clients @(@{ Name = 'Help desk'; Roles = @('Recovery keys') }, @{ Name = 'Old LAPS tool'; Roles = @('LAPS'); Enabled = $false })
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1007 -Cache $cache
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Help desk'
            $row.ResultDetail.TestResult | Should -Not -Match 'Old LAPS tool'
        }

        It 'leaves out clients in AllowedApiClients, by name or client ID' {
            $roles = @{ 'Recovery keys' = @('View Disk Encryption Recovery Key'); 'Lock' = @('View Recovery Lock') }
            $cache = New-IdentitySpecClientCache -Roles $roles -Clients @(@{ Name = 'Help desk'; Roles = @('Recovery keys') }, @{ Name = 'MDM tool'; ClientId = 'abc-123'; Roles = @('Lock') })
            (Invoke-JamfSpecTest -Id MP.JAMF.1007 -Cache $cache -Parameter @{ AllowedApiClients = @('Help desk', 'abc-123') }).Result | Should -Be 'Passed'
        }
    }

    Context 'MP.JAMF.1008 API clients that can change Jamf Pro' {
        It 'passes when no client can change Jamf Pro, leaving out Maester''s own client' {
            $roles = @{ 'Read Only' = @('Read Computers'); 'Admin' = @('Update Computers') }
            $cache = New-IdentitySpecClientCache -Roles $roles -Clients @(@{ Name = 'Inventory sync'; Roles = @('Read Only') }, @{ Name = 'Maester'; ClientId = 'maester-client'; Roles = @('Admin') })
            (Invoke-JamfSpecTest -Id MP.JAMF.1008 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'asks for a review of clients with write privileges' {
            $roles = @{ 'Deploy' = @('Read Computers', 'Create Policies', 'Update Policies', 'Send Computer Remote Lock Command') }
            $cache = New-IdentitySpecClientCache -Roles $roles -Clients @(@{ Name = 'CI pipeline'; Roles = @('Deploy') })
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1008 -Cache $cache
            $row.Result | Should -Be 'Investigate'
            $row.ResultDetail.TestResult | Should -Match '\| CI pipeline \| id-CI pipeline \| Deploy \| 3 \|'
        }

        It 'leaves out clients in AllowedApiClients' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Deploy' = @('Create Policies') } -Clients @(@{ Name = 'CI pipeline'; Roles = @('Deploy') })
            (Invoke-JamfSpecTest -Id MP.JAMF.1008 -Cache $cache -Parameter @{ AllowedApiClients = @('CI pipeline') }).Result | Should -Be 'Passed'
        }
    }

    Context 'MP.JAMF.1009 API client token lifetime' {
        It 'passes with short-lived tokens' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Inventory sync'; Roles = @('Read Only'); Lifetime = 1800 })
            (Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails with a long-lived token' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Reporting'; Roles = @('Read Only'); Lifetime = 7200 })
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match '120 minutes'
        }

        It 'takes the limit from MaximumTokenLifetimeSeconds' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Reporting'; Roles = @('Read Only'); Lifetime = 7200 })
            (Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache -Parameter @{ MaximumTokenLifetimeSeconds = 7200 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when there is no enabled client' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Old'; Roles = @('Read Only'); Enabled = $false })
            (Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1010 supported version' {
        It 'passes on Jamf Cloud whatever the version' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.20.0-t1700000000' }; 'api/v1/cloud-information' = @{ cloudInstance = $true } }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'Jamf Cloud'
        }

        It 'passes on a hosted server at or above the minimum' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.33.1-t1761234567' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails on a hosted server below the minimum' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.9.2-t1700000000' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache
            $row.Result | Should -Be 'Failed'
            $row.Benchmark.Requirement | Should -Be 'V-241798'
        }

        It 'takes the minimum from MinimumVersion' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.25.0' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache -Parameter @{ MinimumVersion = '11.20' }).Result | Should -Be 'Passed'
        }

        It 'asks for a review when the version cannot be read' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = 'unknown' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache).Result | Should -Be 'Investigate'
        }
    }

    Context 'MP.JAMF.1011 sign-in notice' {
        It 'passes with a disclaimer that has text' {
            $cache = @{ 'api/v1/login-customization' = @{ includeCustomDisclaimer = $true; disclaimerHeading = 'Notice'; disclaimerMainText = 'Authorised use only.'; actionText = 'Accept' } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1011 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails when the disclaimer is off' {
            $cache = @{ 'api/v1/login-customization' = @{ includeCustomDisclaimer = $false; disclaimerMainText = 'Authorised use only.' } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1011 -Cache $cache).Result | Should -Be 'Failed'
        }

        It 'fails when the disclaimer text is empty' {
            $cache = @{ 'api/v1/login-customization' = @{ includeCustomDisclaimer = $true; disclaimerMainText = ' ' } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1011 -Cache $cache).Result | Should -Be 'Failed'
        }
    }
}
# Shared by the pack's Pester tests (spec/*.Tests.ps1). Dot-source it in BeforeAll.
#
# The pack reads Jamf through Invoke-JamfProRequest and Get-JamfProPagedResult, which answer from the connection's
# cache before they send anything. The tests fill that cache with recorded answers, so every check runs offline:
# a path that is not in the cache would go to https://fixture.invalid and fail.
#
# A plain path is the answer of Invoke-JamfProRequest; 'paged:<path>?<query>' is the array of results of
# Get-JamfProPagedResult, with the query exactly as the helper builds it.

$script:PackRoot = (Resolve-Path "$PSScriptRoot/..").Path

function Import-JamfSpecMaester {
    $maester = if ($env:MAESTER_MODULE) { $env:MAESTER_MODULE } else { 'Maester' }
    Import-Module $maester -Force -WarningAction SilentlyContinue
    # Loading the pack once registers its services, so the tests can set their connection state.
    $null = Invoke-MtTest -Path $script:PackRoot -Id MP.JAMF.1001 -WarningAction SilentlyContinue
}

function Get-JamfSpecQuery {
    # The queries the pack's helpers send, so fixtures and helpers cannot drift apart.
    param([ValidateSet('Computers', 'MobileDevices', 'Accounts')] [string] $Name)
    switch ($Name) {
        'Computers' { 'paged:api/v4/computers-inventory?section=GENERAL&section=OPERATING_SYSTEM&section=DISK_ENCRYPTION&section=SECURITY&section=EXTENSION_ATTRIBUTES&filter=general.remoteManagement.managed%3D%3Dtrue' }
        'MobileDevices' { 'paged:api/v2/mobile-devices/detail?section=GENERAL&section=SECURITY&exception-handling=LENIENT&filter=managed%3D%3Dtrue' }
        'Accounts' { 'paged:api/v1/accounts?filter=accountStatus%3D%3DEnabled' }
    }
}

function Set-JamfSpecConnection {
    <#
    Connects the pack to recorded answers. -Cache maps paths to answers; hashtables are turned into objects, as
    Invoke-RestMethod returns them.
    #>
    param(
        [hashtable] $Cache = @{},
        [hashtable] $Platform
    )
    $toObject = {
        param($value)
